            break
        grid[x-1][y-1] = value

    # Initialize two 2D arrays to store the maximum values
    dp1 = [[0] * N for _ in range(N)]
    dp2 = [[0] * N for _ in range(N)]

    # Fill the dp1 array for the first path
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp1[i][j] = grid[i][j]
            elif i == 0:
                dp1[i][j] = dp1[i][j-1] + grid[i][j]
            elif j == 0:
                dp1[i][j] = dp1[i-1][j] + grid[i][j]
            else:
                dp1[i][j] = max(dp1[i-1][j], dp1[i][j-1]) + grid[i][j]

    # Fill the dp2 array for the second path
    for i in range(N-1, -1, -1):
        for j in range(N-1, -1, -1):
            if i == N-1 and j == N-1:
                dp2[i][j] = grid[i][j]
            elif i == N-1:
                dp2[i][j] = dp2[i][j+1] + grid[i][j]
            elif j == N-1:
                dp2[i][j] = dp2[i+1][j] + grid[i][j]
            else:
                dp2[i][j] = max(dp2[i+1][j], dp2[i][j+1]) + grid[i][j]

    # Calculate the maximum sum of values collected on the two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            if i == N-1 and j == N-1:
                continue
            max_sum = max(max_sum, dp1[i][j] + dp2[i+1][j] if i < N-1 else dp1[i][j] + dp2[i][j+1])

