def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a 2D array to store the grid values
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if value != 0:
            grid[x-1][y-1] = value

    # Initialize a 3D DP array to store the maximum values collected
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]

    # Initialize the starting point
    dp[0][0][0] = grid[0][0]

    # Directions for moving right and down
    directions = [(0, 1), (1, 0)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for dx, dy in directions:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < N and 0 <= ny < N and k + dx == i:
                        dp[i][j][k] = max(dp[i][j][k], dp[nx][ny][k] + grid[i][j])
                        dp[i][j][i] = max(dp[i][j][i], dp[nx][ny][i] + grid[i][j])

    # Return the maximum value collected on two paths
    return max(dp[N-1][N-1][i] for i in range(N))
