def max_product(num_str: str, N: int, K: int) -> int:
    # Convert the string to a list of integers
    nums = [int(num_str[i]) for i in range(N)]

    # If no multiplication signs are allowed, return the maximum single-digit number
    if K == 0:
        return max(nums)

    # Initialize a list to store the maximum product of subarrays
    dp = [[0] * K for _ in range(N)]

    # Initialize the first row of the DP table
    for i in range(N):
        dp[0][i] = nums[i] * (10 ** i)

    # Fill the DP table
    for k in range(1, K):
        for i in range(k + 1, N):
            dp[k][i] = max(dp[k][j] + nums[i] * (10 ** (i - j)) for j in range(k, i))

    # The result is the maximum value in the last row of the DP table
    return max(dp[-1])
