def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize counters for potential aisle positions
    row_counts = [0] * M
    col_counts = [0] * N

    # Count the number of chatting pairs that can be separated by a horizonal aisle
    for x1, y1, x2, y2 in chatting_pairs:
        if x1 == x2:
            if y1 > y2:
                y1, y2 = y2, y1
            for y in range(y1 + 1, y2):
                row_counts[x1-1] += 1

    # Count the number of chatting pairs that can be separated by a vertical aisle
    for x1, y1, x2, y2 in chatting_pairs:
        if y1 == y2:
            if x1 > x2:
                x1, x2 = x2, x1
            for x in range(x1 + 1, x2):
                col_counts[y1-1] += 1

    # Find the K most effective row positions for horizontal aisles
    effective_rows = sorted(range(M), key=lambda i: row_counts[i], reverse=True)[:K]

    # Find the L most effective column positions for vertical aisles
    effective_cols = sorted(range(N), key=lambda i: col_counts[i], reverse=True)[:L]

    # Format and return the results as strings
    row_result = ' '.join(map(str, effective_rows + [M]))
    col_result = ' '.join(map(str, effective_cols + [N]))

    return row_result, col_result
