        elif i == 1:
            if coeff == 1:
                term = 'x'
            elif coeff == -1:
                term = '-x'
            else:
                term = f'{coeff}x'
        else:
            if coeff == 1:
                term = f'x^{i}'
            elif coeff == -1:
                term = f'-x^{i}'
            else:
                term = f'{coeff}x^{i}'

        terms.append(term)

