        return 0

    count = 0
    quotient = y0 // x0

    for a in range(1, int(math.sqrt(quotient)) + 1):
        if quotient % a == 0:
            b = quotient // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
