    right = [0] * n

    # Calculate the maximum height increasing subsequence ending at each position
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                left[i] = max(left[i], left[j] + 1)

    # Calculate the maximum height decreasing subsequence starting at each position
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                right[i] = max(right[i], right[j] + 1)

    # The minimum number of students to leave is the total number of students
    # minus the maximum length of the increasing followed by decreasing subsequence
    max_length = max(left[i] + right[i] + 1 for i in range(n))
    return n - max_length
