def hanoi_double_iterative(n: int) -> int:
    # For the double-disc Hanoi Towers problem, the minimum number of moves required for n pairs of discs
    # can be computed using the formula: 2^n * (2^n - 1).

    if n <= 0:
        return 0

    return 2 ** n * (2 ** n - 1)
